//! Renderable trait for code generation.
//!
//! This module provides a standardized interface for types that can be
//! rendered to generated files. All generators (makegen, workflow yaml,
//! buck2, etc.) should implement this trait for consistent output format.
//!
//! # Example
//!
//! ```ignore
//! use gunbc_ir::Renderable;
//!
//! struct MyConfig { name: String }
//!
//! impl Renderable for MyConfig {
//!     fn generator_name(&self) -> &str { "gunbc-myconfig" }
//!     fn regenerate_command(&self) -> &str { "make myconfig" }
//!     fn format_id(&self) -> &str { "toml" }
//!     
//!     fn render_content(&self) -> String {
//!         format!("name = {}", self.name)
//!     }
//! }
//!
//! let config = MyConfig { name: "test".into() };
//! let output = config.render();
//! // Output:
//! // # Generated by gunbc-myconfig
//! // # DO NOT EDIT - regenerate with: make myconfig
//! //
//! // name = test
//! ```

use crate::language::traits::comment::{comment_syntax_for, generated_header};

/// Trait for types that can be rendered to generated files.
///
/// Provides standardized headers and regeneration hints across all generators.
/// This unifies the pattern used by makegen, workflow yaml, buck2, and other
/// code generators in the gunbc ecosystem.
pub trait Renderable {
    /// Generator name (e.g., "gunbc-makegen", "gunbc-ci").
    fn generator_name(&self) -> &str;

    /// Command to regenerate (e.g., "make makegen", "make ci-yaml").
    fn regenerate_command(&self) -> &str;

    /// Format identifier for comment syntax lookup.
    ///
    /// Returns a format ID that maps to comment syntax via the language module.
    /// Common values: "makefile", "gitignore", "yaml", "toml", "rust".
    /// Defaults to "hash" (uses # comments).
    fn format_id(&self) -> &str {
        "makefile" // Default to hash comments
    }

    /// Comment prefix for the output format.
    ///
    /// Uses the language module to look up the correct prefix based on `format_id()`.
    /// Falls back to "#" if format is not recognized.
    fn comment_prefix(&self) -> &str {
        comment_syntax_for(self.format_id())
            .map(|s| s.line_prefix)
            .unwrap_or("#")
    }

    /// Render the actual content (without header).
    ///
    /// Implement this to produce the body of the generated file.
    fn render_content(&self) -> String;

    /// Render with standardized header.
    ///
    /// Uses `generated_header()` from the language module for consistency.
    /// Produces output with consistent format:
    /// ```text
    /// {prefix} Generated by {generator_name}
    /// {prefix} DO NOT EDIT - regenerate with: {regenerate_command}
    ///
    /// {content}
    /// ```
    fn render(&self) -> String {
        let prefix = self.comment_prefix();
        let header = generated_header(self.generator_name(), self.regenerate_command(), prefix);
        format!("{}\n\n{}", header, self.render_content())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    struct TestRenderer {
        content: String,
    }

    impl Renderable for TestRenderer {
        fn generator_name(&self) -> &str {
            "gunbc-test"
        }
        fn regenerate_command(&self) -> &str {
            "make test"
        }
        fn format_id(&self) -> &str {
            "makefile"
        }
        fn render_content(&self) -> String {
            self.content.clone()
        }
    }

    #[test]
    fn test_renderable_header() {
        let renderer = TestRenderer {
            content: "hello world".to_string(),
        };
        let output = renderer.render();

        assert!(output.contains("# Generated by gunbc-test"));
        assert!(output.contains("# DO NOT EDIT - regenerate with: make test"));
        assert!(output.contains("hello world"));
    }

    #[test]
    fn test_renderable_rust_format() {
        struct RustRenderer;

        impl Renderable for RustRenderer {
            fn generator_name(&self) -> &str {
                "gunbc-testgen"
            }
            fn regenerate_command(&self) -> &str {
                "make testgen"
            }
            fn format_id(&self) -> &str {
                "rust"
            }
            fn render_content(&self) -> String {
                "fn main() {}".to_string()
            }
        }

        let output = RustRenderer.render();
        // Rust uses "//" as line prefix from language module
        assert!(output.contains("// Generated by gunbc-testgen"));
        assert!(output.contains("// DO NOT EDIT"));
    }

    #[test]
    fn test_renderable_yaml_format() {
        struct YamlRenderer;

        impl Renderable for YamlRenderer {
            fn generator_name(&self) -> &str {
                "gunbc-ci"
            }
            fn regenerate_command(&self) -> &str {
                "make ci-yaml"
            }
            fn format_id(&self) -> &str {
                "yaml"
            }
            fn render_content(&self) -> String {
                "name: ci".to_string()
            }
        }

        let output = YamlRenderer.render();
        assert!(output.contains("# Generated by gunbc-ci"));
    }
}
